const mc=(prompt,options,explanation,scenario='')=>({type:'choice',prompt,options,answer:0,explanation,scenario});
const tf=(prompt,truth,explanation)=>({type:'choice',label:'Verdadero o falso',prompt,options:['Verdadero','Falso'],answer:truth?0:1,explanation});
const multi=(prompt,options,answer,explanation)=>({type:'multi',prompt,options,answer,explanation});
const match=(prompt,pairs,explanation)=>({type:'match',prompt,pairs,explanation});
const order=(prompt,items,explanation)=>({type:'order',prompt,items,explanation});
const L=(id,module,title,goal,paragraphs,example,remember,pages,refs,questions)=>({id,module,title,goal,paragraphs,example,remember,pages,refs,questions:questions.map((q,i)=>({...q,id:`${id}-q${i+1}`,lesson:id}))});
export const LESSONS=[
L('ob1',1,'El mapa de una obligación','Reconocer sujetos, prestación y vínculo.',[
'Una obligación es una relación jurídica: el acreedor puede exigir al deudor una prestación que satisface un interés lícito. Si no se cumple, el derecho ofrece medios para obtener su satisfacción. No es simplemente un deber moral.',
'Los sujetos son acreedor y deudor. La prestación puede consistir en dar, hacer o no hacer; debe ser posible, lícita, determinada o determinable y valorable económicamente. El interés del acreedor también puede ser no patrimonial. El vínculo conecta jurídicamente el crédito y la deuda.'
],'Una imprenta promete entregar 100 apuntes. Quien los encargó es acreedor de esa entrega; la imprenta es deudora. Respecto del precio, los papeles se invierten.','Separá cada prestación: en un contrato bilateral una misma persona puede ser acreedora y deudora.','5–8',[['ccc','arts. 724–726']], [
mc('Respecto de la entrega de los apuntes, ¿quién es acreedor?',['Quien encargó los apuntes','La imprenta','El fabricante del papel'],'El acreedor de la entrega es quien puede exigirla. La imprenta es acreedora de otra prestación: el precio.'),
match('Relacioná cada elemento con su función.',[['Acreedor','Puede exigir la prestación'],['Deudor','Debe cumplir la prestación'],['Vínculo','Une jurídicamente crédito y deuda']],'Los elementos se identifican sobre una prestación concreta, no sobre el contrato en abstracto.'),
tf('El interés del acreedor siempre debe ser económico.',false,'La prestación debe ser valorable económicamente; el interés del acreedor puede ser extrapatrimonial (art. 725).'),
mc('Un músico se compromete a tocar en un evento. ¿Qué debe?',['Una prestación de hacer','Una prestación de no hacer','Transferir necesariamente la propiedad de un bien'],'Tocar en un evento es una actividad: una obligación de hacer.')]),
L('ob2',1,'De dónde nace la deuda','Distinguir causa fuente de finalidad.',[
'No hay obligación sin causa fuente: debe provenir de un hecho que el ordenamiento reconozca como apto para originarla. Entre las fuentes están los contratos, la responsabilidad civil, la gestión de negocios, el enriquecimiento sin causa y la declaración unilateral de voluntad.',
'La causa fuente responde «¿qué hecho originó este deber?». La causa fin pertenece al acto jurídico y atiende a su finalidad. Una obligación de reparar puede nacer de causar un daño, aunque nunca haya existido un contrato entre las personas.'
],'Si rompés por negligencia la vidriera de un comercio, puede nacer el deber de reparar. Su fuente es la responsabilidad civil, no una compra.','No confundas «sin contrato» con «sin obligación».','6–10',[['ccc','arts. 726–727, 1716, 1781, 1794 y 1800']], [
mc('¿Cuál es la fuente del deber de pagar el precio pactado?',['El contrato de compraventa','La mera amistad','La entrega de un pagaré, siempre'],'El acuerdo de compraventa es la causa fuente de la obligación de pagar el precio.'),
mc('Recibís por error un pago que no se te debía. ¿Qué figura orienta el deber de restituir?',['Pago indebido y enriquecimiento sin causa','Donación aceptada automáticamente','Fianza'],'Un desplazamiento patrimonial sin justificación no se transforma por sí solo en una donación.'),
multi('Elegí fuentes que pueden generar obligaciones.', ['Un contrato válido','La responsabilidad por un daño','La gestión de negocios ajenos','Cualquier deseo íntimo no exteriorizado'],[0,1,2],'El ordenamiento reconoce las tres primeras. Un deseo no exteriorizado no basta para generar una obligación jurídica.'),
tf('La causa fuente y la causa fin son preguntas diferentes.',true,'La primera identifica el hecho generador; la segunda analiza la finalidad del acto jurídico.')]),
L('ob3',1,'Cumplir y extinguir','Reconocer pago y otros modos de extinción.',[
'Pagar, en sentido jurídico, es cumplir la prestación debida, no solo entregar dinero. El pago debe respetar identidad, integridad, puntualidad y localización. No se puede imponer al acreedor recibir algo distinto, aunque valga más, ni un pago parcial salvo excepción.',
'Hay otros modos de extinción: compensación (deudas recíprocas que se neutralizan si reúnen los requisitos), confusión (acreedor y deudor se reúnen en una persona), novación (una obligación nueva sustituye a otra con intención de novar) y remisión. Una modificación secundaria no implica novación por sí sola.'
],'Debés entregar una bicicleta determinada. Ofrecer otra más costosa no obliga al acreedor a aceptarla: importa la identidad de la prestación.','Pago no es sinónimo de dinero. Cambiar un detalle no significa novar.','5–10; complemento normativo',[['ccc','arts. 865–869, 921, 931, 933–935 y 950']], [
match('Asociá el supuesto con la figura.',[['Cumplir exactamente lo debido','Pago'],['Reunir acreedor y deudor en una persona','Confusión'],['Sustituir la deuda con intención de novar','Novación']],'Cada figura tiene requisitos propios y produce la extinción por un mecanismo diferente.'),
mc('¿Qué principio impide imponer un bien distinto al prometido?',['Identidad del pago','Publicidad registral','Autonomía cambiaria'],'El art. 868 protege la identidad de lo debido, aunque el sustituto tenga mayor valor.'),
tf('Una prórroga del plazo extingue siempre la obligación por novación.',false,'La intención de novar no se presume. Las modificaciones accesorias no bastan.'),
multi('¿Qué aspectos debe respetar el pago?',['Identidad e integridad','Tiempo y lugar debidos','Solo la buena intención del deudor'],[0,1],'La buena intención no reemplaza el cumplimiento de los requisitos objetivos del pago.')]),
L('ob4',1,'Cuando el cumplimiento se demora','Diferenciar mora del deudor y del acreedor.',[
'La regla del art. 886 es la mora automática por el transcurso del tiempo fijado para cumplir. El art. 887 contempla excepciones: plazo tácito y plazo indeterminado propiamente dicho. En este último se requiere fijación judicial. La eximición por falta de imputabilidad se trata en el art. 888.',
'El acreedor también puede incurrir en mora: sucede si rechaza injustificadamente una oferta de pago que satisface los requisitos legales. El deudor puede recurrir a la consignación si corresponde. La demora puede generar daños e intereses; no todo retraso da automáticamente derecho a resolver cualquier contrato.'
],'Un precio vence el 10 de abril, con plazo expreso y sin regla especial. El deudor no paga: la regla general no exige antes una carta documento.','La mora automática está en el art. 886, aunque un pasaje de la guía mencione por error el 888.','7–11',[['ccc','arts. 886–888 y 904']], [
mc('Con plazo expreso vencido, ¿cuál es la regla general?',['Mora automática','Siempre hace falta demanda judicial','La deuda se extingue'],'La mora se produce por el transcurso del tiempo fijado, salvo excepciones aplicables.'),
mc('El acreedor rechaza sin motivo un pago íntegro y correcto. ¿Qué puede configurarse?',['Mora del acreedor','Novación automática','Extinción automática por abandono'],'La oferta de pago debe ser jurídicamente adecuada y el rechazo injustificado.'),
tf('Si el plazo es indeterminado propiamente dicho, se aplica sin más el mismo mecanismo que a un plazo expreso.',false,'El art. 887 prevé fijación judicial del plazo; no hay que inventar un vencimiento.'),
mc('¿Qué permite liberarse mediante el procedimiento legal ante ciertos obstáculos para pagar?',['La consignación','El endoso','La rescisión de cualquier contrato ajeno'],'La consignación es una vía para pagar cuando se presentan los supuestos legales.')]),
L('ti1',2,'Un derecho que circula','Entender literalidad, autonomía y legitimación.',[
'Los títulos valores facilitan la circulación de derechos. En los títulos cartulares, el documento es necesario para ejercer el derecho conforme a su ley de circulación. También existen títulos no cartulares y modalidades electrónicas: no todo título exige papel.',
'Literalidad: el tenor del título delimita el derecho. Autonomía: quien adquiere de buena fe y conforme a la ley de circulación tiene un derecho propio. Abstracción: en determinados títulos, la relación causal no se opone del mismo modo al tercero protegido. Son conceptos distintos y la protección no elimina todas las defensas posibles.'
],'Una disputa personal entre deudor y un portador anterior no se traslada sin más contra un adquirente posterior de buena fe y legitimado.','La autonomía protege la circulación; no convierte toda firma ni todo título en incuestionables.','11–15',[['ccc','arts. 1815–1816, 1821, 1830–1831 y 1850']], [
match('Uní concepto y significado.',[['Literalidad','El texto delimita el derecho'],['Autonomía','El adquirente protegido tiene un derecho propio'],['Legitimación','Habilitación para ejercer el derecho']],'Literalidad, autonomía y legitimación describen aspectos diferentes.'),
tf('Todos los títulos valores existen únicamente en papel.',false,'El CCyC reconoce títulos no cartulares y la legislación admite modalidades electrónicas.'),
mc('¿Qué presupuesto importa para la protección del adquirente?',['Buena fe y adquisición conforme a la ley de circulación','Ser amigo del librador','Tener una foto de cualquier documento'],'La adquisición regular y de buena fe es central; una foto no prueba por sí sola legitimación.'),
mc('¿Abstracción y autonomía significan exactamente lo mismo?',['No: una mira la causa y la otra la adquisición del derecho','Sí, son idénticas','Ninguna se relaciona con títulos'],'La abstracción se vincula al negocio causal; la autonomía, a la independencia del derecho del adquirente protegido.')]),
L('ti2',2,'Letra de cambio y pagaré','Distinguir la orden de la promesa directa.',[
'La letra de cambio articula una orden de pago: librador, girado y beneficiario son roles que pueden aparecer. El girado pasa a obligado cambiario principal al aceptar. El pagaré contiene la promesa directa del suscriptor, quien asume la obligación principal frente al beneficiario.',
'Los requisitos formales importan: denominación o cláusula admitida, suma, beneficiario, firma y demás menciones legales. No toda omisión produce el mismo efecto: el pagaré sin vencimiento se considera pagadero a la vista. La falta de firma del suscriptor no se suple con esa regla.'
],'«Prometo pagar a Lucía...» orienta a un pagaré. «Pague usted a Lucía...» orienta a la estructura de una letra de cambio.','En el pagaré no se necesita que un girado acepte: el propio suscriptor promete pagar.','12–16',[['letras','arts. 1–2, 28 y 101–104']], [
mc('¿Quién es el obligado principal del pagaré?',['El suscriptor','Un banco necesariamente','Un girado que todavía no aceptó'],'El suscriptor promete directamente el pago (art. 104).'),
match('Relacioná el rol.',[['Librador de una letra','Crea la letra'],['Girado que acepta','Se convierte en aceptante'],['Beneficiario','Es designado para recibir el pago']],'Los roles no siempre corresponden a tres personas distintas, pero deben distinguirse conceptualmente.'),
mc('Un pagaré no indica vencimiento. ¿Qué regla especial se aplica?',['Se considera pagadero a la vista','Es siempre nulo por esa sola omisión','Vence dentro de diez años'],'El art. 102 suple la falta de vencimiento. No suple todos los requisitos.'),
tf('Un pagaré puede obligar cambiariamente al suscriptor sin su firma ni una firma electrónica legalmente admitida.',false,'La firma es requisito: no se reemplaza con la sola mención de su nombre.')]),
L('ti3',2,'El cheque en la práctica','Distinguir tipos, circulación y rechazo.',[
'El cheque contiene una orden de pago dirigida a un banco. La ley distingue cheque común, pagadero a la vista, y cheque de pago diferido, con fecha de pago posterior a la creación dentro del máximo legal de 360 días.',
'La circulación depende de cómo se emitió. Un cheque al portador circula por entrega; uno a favor de persona determinada puede transmitirse por endoso con las condiciones legales. La cláusula «no a la orden» lleva, como regla, a una cesión ordinaria, con excepciones legales. Ante rechazo, la constancia bancaria produce efectos de protesto y habilita el reclamo cambiario cuando corresponde.'
],'Una empresa entrega hoy un cheque de pago diferido para una fecha futura. La disponibilidad de fondos se exige a la fecha legalmente prevista para el pago.','Cheque común no es lo mismo que cheque de pago diferido. Cruzarlo no crea fondos.','13–16',[['cheques','arts. 1–2, 12, 23, 25, 38, 44–46 y 54']], [
match('Relacioná cada instrumento.',[['Cheque común','Pagadero a la vista'],['Cheque de pago diferido','Fecha de pago posterior'],['Constancia bancaria de rechazo','Produce efectos de protesto']],'Las categorías tienen funciones y reglas diferentes.'),
mc('¿Quién recibe la orden de pago en un cheque?',['El banco girado','El escribano','El avalista necesariamente'],'El cheque se libra contra una entidad financiera.'),
tf('Cruzar un cheque garantiza que tenga fondos.',false,'El cruzamiento restringe las modalidades de cobro; no asegura provisión de fondos.'),
mc('¿Cuál es el máximo legal entre creación y fecha de pago del cheque diferido?',['360 días','30 años','No hay máximo'],'La Ley 24.452 fija el máximo de 360 días para la fecha de pago diferido.')]),
L('ti4',2,'Endoso, aval y acciones','Saber qué transmite y qué garantiza.',[
'El endoso transmite derechos y cumple funciones de legitimación y, según su régimen, garantía. El aval garantiza cambiariamente el pago de un obligado. No son intercambiables: transmitir el título no equivale a avalarlo.',
'En letra y pagaré, la acción directa se dirige contra el obligado principal y sus avalistas. La de regreso alcanza a obligados de regreso, con cargas y plazos específicos. La cláusula «sin protesto» dispensa de ese acto, pero no elimina por sí sola la presentación ni los avisos legales.'
],'Un tercero firma como avalista del suscriptor de un pagaré. No se convierte por eso en comprador del negocio que originó el título.','Aval no es endoso. «Sin protesto» tampoco significa «sin ninguna carga».','13–16',[['letras','arts. 12–20, 32–34, 46, 50 y 96']], [
mc('¿Qué función típica cumple el aval?',['Garantizar cambiariamente el pago','Transferir el dominio de un inmueble','Eliminar al deudor principal'],'El aval es una garantía del pago del título, con régimen propio.'),
mc('¿Contra quién procede la acción directa de un pagaré?',['El suscriptor y su avalista','Solo los endosantes','El banco central'],'El suscriptor es obligado principal; sus avalistas quedan comprendidos en la acción directa.'),
tf('La cláusula «sin protesto» elimina todas las cargas del portador.',false,'Dispensa del protesto en su alcance legal; subsisten otras cargas como presentación y avisos.'),
match('Elegí el concepto.',[['Transmitir por firma según la ley cambiaria','Endoso'],['Garantizar el pago cambiario','Aval'],['Constatar formalmente falta de pago o aceptación','Protesto']],'Los tres actos intervienen en momentos y funciones diferentes.')]),
L('co1',3,'Libertad con reglas','Comprender fuerza obligatoria y buena fe.',[
'El contrato es un acto jurídico por el que las partes acuerdan crear, regular, modificar, transferir o extinguir relaciones patrimoniales. La libertad de contratar permite elegir contratar y configurar el contenido, dentro de los límites legales y de orden público.',
'El contrato válido obliga a las partes. La buena fe rige la celebración, interpretación y ejecución: exige conducta leal y cooperación. Libertad contractual no equivale a poder desconocer normas imperativas ni a modificar unilateralmente cualquier acuerdo.'
],'Un proveedor promete una entrega que sabe imposible solo para obtener el anticipo. El análisis no termina en «lo firmaron»: la buena fe importa.','La fuerza obligatoria presupone un contrato válido.','18–24',[['ccc','arts. 957–961']], [
mc('¿Qué significa fuerza obligatoria?',['El contrato válido vincula a las partes','Todo papel firmado es válido','El acreedor puede cambiar siempre el precio'],'La validez es presupuesto; la modificación necesita una causa admitida por el ordenamiento.'),
multi('La buena fe se exige al…',['Celebrar','Interpretar','Ejecutar','Únicamente al pagar en efectivo'],[0,1,2],'El art. 961 abarca esas tres etapas y no se restringe a pagos en efectivo.'),
tf('La autonomía permite dejar sin efecto cualquier norma imperativa.',false,'La libertad contractual tiene límites: las normas indisponibles y el orden público no quedan a voluntad de las partes.'),
mc('¿Qué conducta se ajusta a la buena fe?',['Informar un obstáculo relevante y cooperar','Ocultar deliberadamente datos decisivos','Frustrar a propósito el cumplimiento'],'La lealtad y cooperación orientan la conducta contractual.')]),
L('co2',3,'Cómo se forma el acuerdo','Distinguir aceptación y contraoferta.',[
'Una oferta debe mostrar intención de obligarse y precisiones suficientes. El contrato se concluye por recepción de la aceptación o por conductas que demuestran un acuerdo. La recepción importa cuando la manifestación es conocida o debió ser conocida por su destinatario.',
'La aceptación expresa plena conformidad. Introducir modificaciones supone una nueva propuesta, aunque el oferente puede admitirlas si lo comunica de inmediato. El silencio, por sí solo, no equivale siempre a aceptación: deben existir circunstancias que le den ese valor.'
],'Te ofrecen una notebook por $500.000 y contestás «acepto por $450.000». Cambiaste el precio: no aceptaste la oferta inicial.','Aceptar con un cambio es proponer, no cerrar automáticamente el contrato original.','18–20',[['ccc','arts. 971–983']], [
mc('«Acepto, pero por un precio menor» es…',['Una nueva propuesta','Siempre una aceptación pura','Un pago por consignación'],'Se modifica un elemento de la oferta; se requiere acuerdo sobre la modificación.'),
order('Ordená este caso simplificado de formación entre ausentes.',['La vendedora envía una oferta completa','El comprador emite una aceptación conforme','La aceptación llega a la esfera de recepción de la vendedora'],'En este supuesto, la recepción de una aceptación útil perfecciona el consentimiento.'),
tf('Guardar silencio equivale siempre a aceptar una oferta.',false,'El silencio solo vale como manifestación de voluntad en los supuestos que le atribuyen ese sentido.'),
mc('¿Puede existir acuerdo demostrado por conductas?',['Sí, si son suficientes para mostrarlo','No, todo contrato exige escritura pública','Solo si existe un pagaré'],'El art. 971 contempla el comportamiento concluyente, sin perjuicio de requisitos formales particulares.')]),
L('co3',3,'Objeto, causa y forma','Analizar qué se pacta y cómo se documenta.',[
'El objeto debe ser lícito, posible, determinado o determinable y valorable económicamente. La causa atiende a la finalidad jurídicamente relevante y debe ser lícita. No basta con que las partes quieran algo para que sea válido.',
'Rige libertad de formas salvo exigencia legal. En ciertos casos se requiere escritura pública; en otros, un instrumento escrito. Hay contratos bilaterales o unilaterales, onerosos o gratuitos, conmutativos o aleatorios: cada clasificación utiliza un criterio diferente.'
],'Una compraventa habitual tiene prestaciones recíprocas y ventajas a cambio de sacrificios: es bilateral y onerosa. Un seguro es aleatorio, porque la prestación depende del evento cubierto.','Unilateral no significa «firmado por una sola persona»: clasifica las obligaciones que nacen.','18–25',[['ccc','arts. 966–969, 1003–1004 y 1012–1018']], [
match('Relacioná la clasificación.',[['Bilateral','Genera obligaciones recíprocas'],['Gratuito','Una parte recibe una ventaja sin contraprestación a su cargo'],['Aleatorio','Ventajas o pérdidas dependen de un acontecimiento incierto']],'Las clasificaciones atienden a criterios distintos.'),
mc('¿Qué requisito debe cumplir el objeto?',['Ser lícito y posible','Ser necesariamente un inmueble','Estar siempre ya individualizado sin admitir determinación posterior'],'El objeto puede ser determinable si existen criterios suficientes para precisarlo.'),
tf('Todos los contratos requieren escritura pública.',false,'Rige libertad de formas, salvo que la ley imponga una formalidad particular.'),
mc('Dos personas pactan una finalidad ilícita común. ¿Qué problema aparece?',['Ilicitud de la causa','Mora del acreedor necesariamente','Un simple error de fecha sin importancia'],'La causa ilícita compromete la validez: el consentimiento no sanea cualquier finalidad.')]),
L('co4',3,'Efectos, conflictos y consumo','Elegir el mecanismo jurídico adecuado.',[
'Como regla, el contrato produce efectos entre sus partes y no impone obligaciones a terceros. Existen figuras especiales, como la estipulación a favor de tercero. Ante incumplimiento pueden corresponder cumplimiento, daños o resolución, cada uno con sus requisitos.',
'Rescisión bilateral es el acuerdo para dejar sin efecto el contrato; resolución se relaciona con una causa prevista, como incumplimiento relevante. La imprevisión atiende a una alteración extraordinaria que vuelve excesivamente onerosa una prestación bajo condiciones legales. En adhesión y consumo rigen controles específicos y criterios favorables al adherente o consumidor.'
],'Una cláusula predispuesta ambigua no se interpreta automáticamente a favor de quien la redactó. El régimen protege al adherente mediante reglas especiales.','No confundas incumplimiento, imposibilidad, frustración del fin e imprevisión: analizá el supuesto.','19–29',[['ccc','arts. 987–989, 1021–1027, 1061–1068, 1076–1091 y 1094–1095']], [
mc('Ambas partes acuerdan terminar el contrato. ¿Qué figura describe eso?',['Rescisión bilateral','Mora automática','Aval'],'La rescisión bilateral nace de un nuevo acuerdo extintivo.'),
tf('Un contrato puede imponer libremente una deuda a una persona que no participó.',false,'El efecto relativo impide imponer obligaciones a terceros por la sola voluntad de las partes.'),
mc('Una cláusula predispuesta es ambigua. ¿Contra quién se interpreta en el régimen de adhesión?',['Contra quien la predispuso','Siempre contra quien adhirió','Contra cualquier tercero'],'El art. 987 establece interpretación contra el predisponente.'),
mc('Un cambio extraordinario ajeno al riesgo asumido vuelve excesivamente onerosa una prestación. ¿Qué figura hay que analizar?',['Imprevisión','Endoso en blanco','Compensación automática'],'La imprevisión del art. 1091 requiere presupuestos específicos; no cualquier aumento de costos basta.')]),
L('tr1',4,'Compraventa','Diferenciar el contrato de la transferencia del derecho.',[
'En la compraventa una parte se obliga a transferir la propiedad de una cosa y la otra a pagar un precio en dinero. El vendedor debe entregar y realizar lo necesario para transferir; el comprador debe pagar y recibir en los términos correspondientes.',
'El contrato y la adquisición del derecho real son planos distintos: para adquirir el dominio se requieren los recaudos legales de título y modo que correspondan. Las garantías de saneamiento incluyen evicción y vicios ocultos, con alcances, exclusiones y plazos legales propios.'
],'Comprar una máquina no es lo mismo que alquilarla: la compraventa apunta a transferir propiedad; la locación, a conceder uso y goce temporarios.','Obligarse a transferir no es necesariamente haber transferido ya.','30–34',[['ccc','arts. 1033–1058, 1123, 1137–1141 y 1892']], [
mc('¿Qué contraprestación caracteriza la compraventa?',['Un precio en dinero','Solo otra cosa sin dinero','La mera custodia gratuita'],'El precio en dinero es un elemento tipificante.'),
tf('Firmar una compraventa siempre basta, por sí solo, para adquirir todo derecho real sobre cualquier bien.',false,'Debe distinguirse el contrato de los requisitos de adquisición del derecho real.'),
match('Relacioná obligación y parte.',[['Transferir y entregar la cosa','Vendedor'],['Pagar el precio','Comprador'],['Responder por saneamiento cuando corresponde','Transmitente obligado a sanear']],'El contenido concreto depende del contrato y del régimen legal.'),
mc('Un defecto oculto relevante de una máquina lleva a examinar…',['La garantía por vicios ocultos','La aceptación de la letra','La excusión del fiador'],'Los vicios ocultos forman parte del régimen de saneamiento, con sus requisitos y cargas.')]),
L('tr2',4,'Permuta y precio mixto','Identificar cuándo hay intercambio de cosas.',[
'La permuta implica que las partes se obligan recíprocamente a transferirse el dominio de cosas que no son dinero. En lo compatible se aplican supletoriamente las reglas de la compraventa.',
'Si el precio combina cosa y dinero, el art. 1126 proporciona un criterio: hay permuta si el valor de la cosa es mayor que el dinero; en los demás casos hay compraventa. Para resolver, compará los valores y no solo el nombre que eligieron las partes.'
],'Se entrega una cosa valuada en $700 y $300 en dinero como contraprestación. Predomina el valor de la cosa: el criterio legal lleva a permuta.','Con valores iguales de cosa y dinero, el art. 1126 lleva a compraventa.','32–34',[['ccc','arts. 1126 y 1172–1175']], [
mc('Intercambiar una bicicleta por una cámara, sin dinero, es típicamente…',['Permuta','Locación','Depósito'],'Se intercambian cosas, con obligación recíproca de transferir su dominio.'),
mc('La contraprestación es una cosa de $300 más $700 en dinero. ¿Qué regla aplica?',['Compraventa','Permuta','Comodato'],'El dinero tiene mayor valor que la cosa; corresponde compraventa.'),
tf('Si cosa y dinero valen lo mismo, el contrato se califica como permuta por el art. 1126.',false,'La permuta exige que sea mayor el valor de la cosa. En los demás casos es compraventa.'),
mc('¿Qué régimen se aplica supletoriamente a la permuta, en lo compatible?',['Compraventa','Seguro de vida','Cheque diferido'],'El art. 1175 remite al régimen de compraventa.')]),
L('tr3',4,'Cesión de derechos','Distinguir cedente, cesionario y deudor cedido.',[
'En la cesión una parte transfiere a otra un derecho. El cedente lo transmite y el cesionario lo adquiere. El deudor cedido no se convierte por eso en parte del contrato de cesión. No todos los derechos son transmisibles.',
'La cesión debe hacerse por escrito como regla, con excepciones y supuestos que requieren escritura pública. La notificación al deudor cedido es relevante para efectos frente a terceros; no debe confundirse con un consentimiento universalmente necesario. Una cesión de crédito no es lo mismo que sustituir íntegramente una posición contractual.'
],'Ana tiene un crédito contra Bruno y lo cede a Carla. Ana es cedente, Carla cesionaria y Bruno deudor cedido.','Cambiar al acreedor no cambia automáticamente el importe ni la deuda.','32–36',[['ccc','arts. 1614–1621 y 1636']], [
match('En la cesión de Ana a Carla del crédito contra Bruno…',[['Ana','Cedente'],['Carla','Cesionaria'],['Bruno','Deudor cedido']],'Cedente y cesionario celebran la cesión; el deudor cedido conserva su rol de deudor.'),
tf('La cesión de crédito exige siempre la aceptación del deudor cedido.',false,'No debe confundirse la notificación y oponibilidad con un consentimiento siempre necesario.'),
mc('¿Cuál es la regla de forma de la cesión?',['Por escrito, con excepciones y casos de escritura pública','Siempre verbal','Siempre basta una promesa secreta'],'El art. 1618 fija la forma y supuestos especiales.'),
mc('¿Qué ejemplo exige escritura pública según el art. 1618?',['Cesión de derechos hereditarios','Todo endoso de cheque','Préstamo de una lapicera'],'Los derechos hereditarios integran uno de los supuestos expresos.')]),
L('tr4',4,'Fondo de comercio y venta internacional','Reconocer publicidad, acreedores y distribución de riesgos.',[
'La transferencia de un fondo de comercio puede abarcar elementos como instalaciones, mercaderías, nombre y clientela. La Ley 11.867 protege a los acreedores mediante publicidad, posibilidad de oposición, retención y depósito. No equivale a vender las acciones de una sociedad.',
'En una compraventa internacional importan la ley aplicable y, cuando corresponde, la Convención de Viena. Los Incoterms incorporados al acuerdo distribuyen ciertas obligaciones, gastos y riesgos de entrega; no reemplazan todo el contrato ni determinan por sí solos la transferencia de propiedad.'
],'Al adquirir un comercio no alcanza con pagar al vendedor y cambiar el cartel: deben examinarse las reglas de publicidad y protección de acreedores.','Incoterms: entrega, costos y riesgos. No son una ley universal del contrato.','30–36',[['fondo','arts. 1–7'],['icc','entrega, costos y riesgos'],['cisg','ámbito de aplicación']], [
order('Ordená este esquema del procedimiento, suponiendo oposición de un acreedor.',['Publicaciones legales de la transferencia','Oposición del acreedor dentro del plazo','Retención y depósito según la ley','Instrumentación e inscripción cumpliendo los requisitos'],'Es un esquema didáctico: la Ley 11.867 regula plazos y condiciones para cada etapa.'),
mc('¿Qué protege principalmente la oposición del acreedor?',['La posibilidad de cobrar su crédito mediante retención y depósito','Su derecho a quedarse siempre con el negocio','Una prohibición absoluta de transferir'],'El procedimiento protege el crédito; no atribuye automáticamente el fondo al acreedor.'),
tf('Los Incoterms determinan por sí solos la transmisión del dominio.',false,'Su función se centra en obligaciones, costos y riesgos de entrega, no en toda la regulación contractual.'),
mc('¿Vender un fondo y vender acciones sociales son la misma operación?',['No, el objeto y el régimen son diferentes','Sí, siempre','Solo cambia el nombre del documento'],'Una operación recae sobre el establecimiento; la otra sobre participaciones sociales.')]),
L('us1',5,'Locación','Entender el uso temporario a cambio de dinero.',[
'La locación concede el uso y goce temporario de una cosa por un precio en dinero. El locador debe entregarla y conservarla apta para el uso convenido; el locatario debe pagar, usarla según el destino, conservarla y restituirla.',
'El régimen de alquileres sufrió reformas. No memorices un plazo mínimo universal tomado de apuntes antiguos: el texto vigente contempla el plazo que establezcan las partes y reglas supletorias para cuando no lo fijaron. La forma escrita se exige, entre otros casos, para inmuebles y muebles registrables.'
],'Una empresa paga mensualmente por usar un local y debe devolverlo al terminar. El uso es temporal; no está comprando el inmueble.','Para plazos y moneda, verificá el texto vigente y el supuesto concreto.','37–40',[['ccc','arts. 1187–1188, 1197–1201 y 1205–1210']], [
mc('¿Qué recibe típicamente el locatario?',['Uso y goce temporarios','Dominio definitivo','Una garantía cambiaria'],'La locación permite usar y gozar; no transfiere el dominio.'),
multi('Son obligaciones típicas del locatario…',['Pagar el canon','Respetar el destino de uso','Restituir al finalizar','Vender la cosa como propia'],[0,1,2],'El locatario debe cumplir el pago, uso debido y restitución. No adquiere facultad de vender el bien como dueño.'),
tf('Todo alquiler actual tiene necesariamente el mismo plazo mínimo legal, sin importar el acuerdo y el destino.',false,'Las reformas exigen distinguir plazo pactado, reglas supletorias y destino.'),
mc('El locador debe, como regla…',['Entregar y conservar la cosa apta para el uso convenido','Garantizar las ventas del negocio del locatario','Transferir gratis el inmueble al finalizar'],'Las obligaciones del locador se vinculan a la aptitud para el uso, no al éxito comercial del locatario.')]),
L('us2',5,'Leasing','Detectar la opción de compra.',[
'En el leasing el dador transfiere la tenencia de un bien para uso y goce, a cambio de un canon, y confiere una opción de compra por un precio. Esa opción lo distingue de una locación común. No equivale a que la propiedad se transfiera desde el comienzo.',
'Puede recaer en distintos bienes admitidos legalmente, incluso software. La inscripción es relevante frente a terceros. El ejercicio de la opción se rige por el acuerdo y la ley; el esquema combina uso y una eventual adquisición.'
],'Una empresa usa una máquina pagando cánones y puede comprarla por el precio de opción pactado. Esa alternativa es central para identificar el leasing.','Canon + uso + opción de compra: buscá esos elementos juntos.','37–40',[['ccc','arts. 1227–1234 y 1240–1242']], [
mc('¿Qué rasgo distingue especialmente al leasing de la locación?',['La opción de compra','La ausencia absoluta de precio','La obligación de custodiar sin usar'],'El leasing incorpora una opción de adquisición por el precio previsto.'),
tf('El tomador se convierte necesariamente en dueño al pagar el primer canon.',false,'El leasing transfiere tenencia para uso y goce; la adquisición exige el mecanismo de opción y requisitos correspondientes.'),
match('Relacioná los términos.',[['Dador','Concede tenencia y opción de compra'],['Tomador','Usa el bien y paga el canon'],['Opción','Permite decidir la adquisición']],'La opción es un derecho del tomador, no una compra ya consumada.'),
mc('¿Para qué es relevante la inscripción del leasing?',['Para su oponibilidad frente a terceros','Para sustituir siempre el consentimiento','Para volverlo gratuito'],'La publicidad registral cumple la función de oponibilidad en los términos legales.')]),
L('us3',5,'Comodato','Distinguir prestar el uso de prestar para consumir.',[
'El comodato permite servirse gratuitamente de una cosa y devolver la misma recibida. Como figura típica recae sobre una cosa no fungible, aunque la ley admite cosas fungibles si se pacta devolver exactamente las mismas.',
'El comodatario debe conservar, usar conforme al destino y restituir. En el mutuo, en cambio, se entrega en propiedad una cantidad de cosas fungibles y se devuelve un equivalente en especie, calidad y cantidad. La gratuidad distingue al comodato de la locación.'
],'Te prestan una cámara para un viaje y debés devolver esa misma cámara: comodato. Te prestan dinero para gastarlo y devolver otro tanto: mutuo.','La pregunta decisiva: ¿devuelvo la misma cosa o un equivalente?','37–40',[['ccc','arts. 1525 y 1533–1541']], [
mc('Te prestan gratuitamente una bicicleta individualizada y devolvés esa misma. Es…',['Comodato','Mutuo típico','Compraventa'],'Se concede el uso gratuito con restitución de la misma cosa.'),
tf('El comodato tiene como elemento típico el cobro de un alquiler.',false,'Es esencialmente gratuito. El pago por uso orienta a otra figura, como locación.'),
match('Relacioná el caso.',[['Usar gratis y devolver la misma cámara','Comodato'],['Usar un local pagando alquiler','Locación'],['Consumir dinero y restituir equivalente','Mutuo']],'No todos los préstamos tienen el mismo objeto ni los mismos efectos.'),
mc('¿Qué debe hacer el comodatario?',['Conservar y restituir conforme al contrato','Vender el bien sin autorización','Quedarse siempre con la cosa por el uso'],'La concesión de uso no transfiere dominio ni elimina el deber de restitución.')]),
L('us4',6,'Mandato y representación','Separar el encargo de actuar en nombre ajeno.',[
'El mandato es el contrato por el que alguien se obliga a realizar actos jurídicos en interés de otra persona. Se presume oneroso. La representación permite que la actuación en nombre y dentro de las facultades de otro produzca efectos directamente para el representado.',
'Puede haber mandato sin representación: el mandatario actúa en nombre propio, aunque en interés ajeno. La consignación es un mandato sin representación para vender cosas muebles. La gestión de negocios nace de asumir razonablemente un negocio ajeno sin autorización ni obligación previa; no es un mandato pactado.'
],'Carla encarga a Diego una compra. Si Diego actúa en nombre de Carla y dentro de su poder, el vínculo se produce directamente para ella. Si contrata en nombre propio, hay que distinguir ese esquema.','Mandato = relación de encargo. Representación = efectos de actuar en nombre ajeno.','37–41',[['ccc','arts. 358–359, 1319–1324, 1335 y 1781']], [
tf('Todo mandato incluye necesariamente representación.',false,'El CCyC contempla mandato sin representación.'),
match('Relacioná cada figura.',[['Mandato','Encargo contractual de actos jurídicos'],['Consignación','Mandato sin representación para vender muebles'],['Gestión de negocios','Intervención sin autorización previa por motivo razonable']],'La gestión no nace del mismo acuerdo previo que el mandato.'),
mc('¿Qué debe hacer típicamente el mandatario?',['Actuar diligentemente, informar y rendir cuentas','Anteponer siempre su interés al del mandante','Guardar en secreto el resultado del encargo'],'El mandato incorpora deberes de diligencia, información y rendición de cuentas.'),
mc('La actuación del representante dentro de sus facultades y en nombre ajeno produce efectos…',['Directamente para el representado','Siempre solo para el representante','Solo después de una donación'],'Ese efecto directo caracteriza la representación (art. 359).')]),
L('us5',6,'Donación','Reconocer gratuidad, aceptación y solemnidad.',[
'Hay donación cuando alguien se obliga a transferir gratuitamente una cosa a otra persona y esta acepta. La intención de beneficiar importa, pero no reemplaza el consentimiento ni la forma legal.',
'Las donaciones de inmuebles, muebles registrables y prestaciones periódicas o vitalicias requieren escritura pública bajo pena de nulidad. No hay que trasladar a este caso cualquier regla sobre promesas de escriturar. Las donaciones con cargo o remuneratorias requieren analizar sus particularidades.'
],'Donar una casa no se completa jurídicamente con un mensaje que diga «te la regalo». Debe cumplirse la formalidad solemne aplicable.','Gratuito no significa sin reglas. Donar exige aceptación y, a veces, forma solemne.','38–40',[['ccc','arts. 1542–1545, 1552 y 1561–1564']], [
mc('¿Qué elemento corresponde a una donación?',['Transferencia gratuita de una cosa aceptada por el donatario','Uso temporario por un precio','Garantía de una deuda ajena'],'La donación apunta a transferir gratuitamente, con aceptación.'),
tf('La donación de un inmueble puede hacerse válidamente por un simple mensaje sin escritura.',false,'El art. 1552 exige escritura pública bajo pena de nulidad.'),
multi('¿Cuáles están expresamente sometidas a escritura pública por el art. 1552?',['Donación de inmuebles','Donación de muebles registrables','Donación de prestaciones periódicas o vitalicias','Cualquier regalo manual de un libro'],[0,1,2],'Esos son los supuestos expresos de solemnidad del artículo.'),
mc('¿Toda donación puede revocarse libremente porque el donante cambió de opinión?',['No, deben darse causas admitidas legalmente','Sí, en cualquier momento y sin causa','Sí, solo basta enviar un emoji'],'La donación no queda librada al arrepentimiento ilimitado del donante.')]),

L('re1',6,'Intervenir en un asunto ajeno','Separar mandato, gestión de negocios y empleo útil.',[
'El mandato nace de un acuerdo para realizar actos jurídicos en interés ajeno. Puede aceptarse expresa o tácitamente; si se acompaña de poder, su forma debe respetar la exigida para el acto a realizar. El mandatario debe seguir instrucciones, informar conflictos, actuar diligentemente y rendir cuentas; el mandante debe cumplir las obligaciones económicas pertinentes.',
'En la gestión de negocios alguien asume razonablemente un asunto ajeno sin autorización, obligación previa ni intención de liberalidad. Debe avisar, actuar según interés presumible y rendir cuentas. La gestión útil puede generar reembolso de gastos necesarios y útiles. El empleo útil contempla gastos en interés ajeno, sin ser gestor ni mandatario, reembolsables en cuanto resulten de utilidad.',
'La consignación es mandato sin representación para vender muebles: el consignatario contrata en nombre propio y queda obligado frente al tercero. Debe seguir instrucciones, observar diligencia al otorgar crédito y no comprar para sí las cosas consignadas. No es lo mismo que consignar un pago ante rechazo del acreedor.'
],'Encargar por contrato una venta es mandato; cuidar sin encargo un asunto urgente del vecino puede ser gestión. Pagar un gasto útil en interés ajeno requiere analizar empleo útil y su límite.','Encargo, iniciativa razonable y utilidad del gasto son criterios diferentes.','37–41',[['ccc','arts. 363, 1319–1328, 1335–1342, 1781–1785 y 1791–1793']], [
match('Relacioná el origen de cada intervención.',[['Encargo de actos jurídicos','Mandato'],['Asumir razonablemente negocio ajeno sin encargo','Gestión de negocios'],['Gasto en interés ajeno sin ser gestor ni mandatario','Empleo útil']],'La finalidad útil no convierte toda ayuda en un mandato.'),
tf('El consignatario actúa necesariamente en nombre del consignante.',false,'La consignación es mandato sin representación para vender muebles: actúa en nombre propio.'),
mc('¿Cuánto permite reclamar el empleo útil?',['El gasto en cuanto resulte útil, según el régimen','Cualquier suma que decida quien gastó','Una comisión comercial automática'],'Debe acreditarse utilidad; el gasto unilateral no traslada cualquier costo.'),
mc('¿Qué es relevante para distinguir gestión de una ayuda gratuita?',['Ausencia de intención de liberalidad y los demás requisitos legales','Que el vecino tenga más dinero','Que la ayuda dure más de cinco minutos'],'La gestión del art. 1781 exige motivo razonable y ausencia de encargo, deber e intención liberal.')]),
L('re2',6,'Cuando termina el encargo','Distinguir fin del mandato, del poder y protección de terceros.',[
'El mandato puede extinguirse por plazo, condición, ejecución del negocio, revocación, renuncia, muerte o incapacidad. Las reglas sobre irrevocabilidad y urgencia introducen excepciones y deberes residuales. Revocar sin justa causa un mandato determinado o renunciar intempestivamente puede generar daños.',
'Mandato y poder no son idénticos. La extinción del poder tiene reglas propias: revocación y modificaciones deben comunicarse a terceros por medios idóneos; sin ello no son oponibles salvo conocimiento. Si muere el mandante, puede ser necesario cumplir actos de conservación ante peligro en la demora, con las salvedades legales. No abandonar un asunto urgente alegando sólo que terminó el contrato.'
],'Un mandatario renuncia el día de un vencimiento sin aviso y causa una pérdida evitable. Analizá fin del vínculo y eventual responsabilidad por el modo de terminarlo.','Extinguir el vínculo no borra rendición de cuentas, aviso ni daños por una terminación irregular.','37–41',[['ccc','arts. 380–381 y 1329–1334']], [
tf('Revocar un poder sólo en privado siempre lo vuelve oponible a terceros que lo ignoran sin culpa.',false,'La comunicación por medios idóneos y el conocimiento de terceros son centrales bajo art. 381.'),
mc('Ante muerte del mandante y peligro en la demora, el mandatario…',['Debe considerar actos conservatorios y las instrucciones pertinentes','Puede apropiarse de los bienes','Queda siempre liberado de toda actuación urgente'],'El art. 1333 prevé conservación ante peligro en la demora, salvo instrucciones expresas pertinentes.'),
multi('¿Qué puede extinguir un mandato?',['Ejecución del negocio','Revocación del mandante','Renuncia del mandatario','Cualquier aumento de precios, automáticamente'],[0,1,2],'El art. 1329 enumera causas; no incluye cualquier variación de costos.'),
tf('La renuncia intempestiva sin causa justificada puede originar indemnización.',true,'Art. 1332: se deben los daños que cause al mandante.')]),
L('re3',6,'Donación: cargo, reversión y revocación','Reconocer por qué puede cambiar una liberalidad.',[
'Puede donar quien tiene plena capacidad de disponer y aceptar quien tiene capacidad, con reglas de representación para incapaces y para donaciones con cargo. Aceptación y forma son esenciales. En donaciones remuneratorias o con cargo, se considera onerosa la parte equivalente al servicio o carga y liberal el excedente.',
'Reversión es una condición resolutoria expresa a favor del donante por fallecimiento en los supuestos legales: no equivale al mero arrepentimiento. Revocación admite inejecución de cargos, ingratitud y, si se pactó, supernacencia de hijos. La ingratitud comprende causas legalmente previstas, no cualquier desacuerdo familiar.',
'La donación inoficiosa excede la porción disponible y se vincula con protección de la legítima. Su análisis no es el mismo que nulidad formal o revocación por ingratitud: requiere régimen sucesorio y presupuestos propios. No afirmar que toda donación se anula íntegramente apenas afecta expectativas hereditarias.'
],'Donar con cargo de mantener una biblioteca y luego incumplirlo plantea revocación por cargo. Pactar devolución si el donatario fallece primero plantea reversión.','Identificá si hay condición pactada, causa de revocación o afectación de legítima.','38–40',[['ccc','arts. 1548–1549 y 1561–1574']], [
match('Elegí la figura.',[['Condición expresa por premoriencia del donatario','Reversión'],['Ingratitud en supuestos legales','Revocación'],['Exceso sobre porción disponible','Inoficiosidad']],'Cada figura tiene causa y efectos propios.'),
tf('Tener un hijo después permite siempre revocar cualquier donación anterior.',false,'La revocación por supernacencia de hijos requiere estipulación expresa.'),
mc('¿Una donación con cargo es enteramente onerosa sin mirar valores?',['No, se considera la equivalencia entre cargo y bien','Sí, por llamarse cargo','Sí, aunque el cargo sea insignificante'],'El art. 1564 distingue la parte equivalente y el excedente liberal.'),
mc('Una pelea familiar permite revocar por ingratitud…',['Sólo si encuadra en causas legales y se cumplen sus requisitos','En todos los casos, sin prueba','Si el donante se arrepiente después'],'La ingratitud no equivale a cualquier desacuerdo y requiere la causa legal pertinente.')]),
L('ga1',7,'Fianza','Comprender una garantía personal accesoria.',[
'El fiador se obliga accesoriamente por otra persona a satisfacer una prestación si se incumple. Es una garantía personal: agrega un obligado, en lugar de afectar necesariamente un bien específico.',
'En la fianza simple existe como regla beneficio de excusión: deben ejecutarse antes los bienes del deudor, con excepciones legales. La fianza solidaria y el principal pagador tienen reglas diferentes; este último se considera deudor solidario. El fiador que paga se subroga en los derechos del acreedor.'
],'Un fiador simple invoca la excusión: pide que primero se persigan los bienes del deudor principal. No está diciendo que la deuda no exista.','Fianza simple, fianza solidaria y principal pagador no son etiquetas intercambiables.','42–45',[['ccc','arts. 1574, 1579, 1583–1592']], [
mc('¿Qué tipo de garantía es la fianza?',['Personal','Real sobre una cosa determinada necesariamente','Una transmisión cambiaria'],'La fianza incorpora una obligación accesoria de otra persona.'),
mc('¿Qué permite el beneficio de excusión, como regla?',['Exigir la ejecución previa de bienes del deudor','Borrar la deuda sin pago','Cobrar antes que todos los acreedores sobre un bien propio'],'La excusión ordena la persecución patrimonial, salvo excepciones.'),
tf('El principal pagador se considera deudor solidario.',true,'Así lo dispone el art. 1591, aunque se utilice el nombre de fiador.'),
mc('Cuando el fiador paga, normalmente…',['Se subroga y puede reclamar al deudor lo correspondiente','Pierde necesariamente todo derecho a reembolso','Se convierte en propietario de todos los bienes del deudor'],'La subrogación permite ejercer los derechos del acreedor con el alcance legal.')]),
L('ga2',7,'Prenda','Identificar una garantía real.',[
'La prenda común es un derecho real de garantía sobre cosas muebles no registrables o créditos instrumentados. Se constituye conforme a sus requisitos, incluyendo instrumento y entrega en los casos correspondientes. Afecta un bien al pago de una obligación.',
'La prenda con registro tiene un régimen especial que permite conservar la tenencia en los supuestos legales. No debe reducirse a «solo bienes registrables». La preferencia de cobro sobre el bien no significa que el acreedor se convierta automáticamente en dueño por falta de pago.'
],'Una cosa queda afectada para asegurar una deuda. Si se incumple, el acreedor debe utilizar el procedimiento de ejecución aplicable; no basta con decir «ahora es mía».','Garantía personal: otro obligado. Garantía real: un bien afectado.','42–44',[['ccc','arts. 2184–2198 y 2219–2220']], [
match('Asociá garantía y mecanismo.',[['Fianza','Obligación accesoria de otra persona'],['Prenda','Afectación real de un bien'],['Preferencia','Prioridad de cobro con el alcance legal']],'La preferencia no equivale a dominio automático.'),
tf('El acreedor prendario se vuelve dueño automáticamente al incumplirse la deuda.',false,'Debe respetarse el procedimiento legal de ejecución; no hay apropiación automática general.'),
mc('La prenda común del CCyC puede recaer en…',['Muebles no registrables o créditos instrumentados','Únicamente edificios','Cualquier obligación moral'],'El art. 2219 delimita su objeto.'),
mc('¿La prenda con registro tiene reglas especiales?',['Sí, no se debe confundir con la prenda común','No, siempre exige la misma entrega física','No existe en Argentina'],'El art. 2220 remite al régimen especial.')]),
L('ga3',7,'Depósito y mutuo','Distinguir guardar de prestar para consumir.',[
'En el depósito alguien recibe una cosa para custodiarla y restituirla con sus frutos. Se presume oneroso. En el depósito regular la finalidad principal es la guarda, no usar la cosa en beneficio propio.',
'En el mutuo se promete entregar en propiedad una cantidad de cosas fungibles, con devolución de igual especie, calidad y cantidad. También se presume oneroso, salvo pacto en contrario. El depósito irregular tiene particularidades: según el supuesto, se transfiere el dominio y se restituyen equivalentes. La finalidad ayuda a diferenciar las figuras.'
],'Dejás una valija para que la guarden: depósito. Recibís dinero para gastarlo y restituir equivalente: mutuo. Recibís una cámara gratis para devolver la misma: comodato.','Custodiar, consumir y usar no son la misma finalidad.','42–44',[['ccc','arts. 1356–1367 y 1525–1530']], [
match('Clasificá por finalidad.',[['Guardar y restituir una valija','Depósito'],['Recibir dinero en propiedad y devolver equivalente','Mutuo'],['Usar gratis y devolver la misma cámara','Comodato']],'Analizar finalidad, transferencia de dominio y restitución evita confusiones.'),
tf('El mutuo se presume gratuito en el CCyC.',false,'El art. 1527 presume onerosidad salvo pacto en contrario.'),
mc('En un mutuo de dinero se debe devolver…',['Igual cantidad conforme al contrato y los intereses que correspondan','Necesariamente los mismos billetes','Una cosa cualquiera de parecido valor'],'Se restituye equivalente, no la identidad física de los billetes.'),
mc('El depositario regular recibe una cosa principalmente para…',['Custodiarla y restituirla','Consumirla como dueño','Venderla sin instrucciones'],'La finalidad tipificante del depósito es la guarda.')]),
L('ga4',7,'Seguro y riesgo','Distinguir prima, póliza y siniestro.',[
'Por el seguro, el asegurador asume una prestación para el caso del evento previsto, a cambio de una prima. Riesgo es la eventualidad cubierta; siniestro, su realización. Póliza es el documento del contrato: no debe confundirse con la prima ni con el evento.',
'El alcance depende del riesgo cubierto, exclusiones válidas, suma asegurada y franquicia, si existe. La denuncia del siniestro y la información sobre el riesgo tienen consecuencias legales. En el seguro de daños rige una función indemnizatoria; no es una vía para enriquecerse por encima del daño cubierto. En seguros de personas la prestación responde al régimen correspondiente.'
],'Una póliza de incendio no cubre automáticamente cualquier pérdida del negocio. Hay que identificar el riesgo, el evento ocurrido y el alcance pactado conforme a la ley.','Que exista una póliza no significa que todo evento esté cubierto.','43–45',[['seguros','arts. 1, 4, 11, 37, 46–47, 61 y 109']], [
match('Relacioná el vocabulario.',[['Prima','Precio del seguro'],['Póliza','Documento del contrato'],['Siniestro','Realización del evento previsto']],'Separá el precio, el documento y el acontecimiento.'),
mc('¿Qué hay que examinar ante un siniestro?',['Riesgo cubierto, exclusiones válidas y límites aplicables','Solo el color de la póliza','Únicamente si el asegurado pagó alguna vez'],'La cobertura requiere examinar el contrato y el régimen legal, además de las cargas pertinentes.'),
tf('En el seguro de daños, la indemnización permite siempre ganar más que el daño cubierto.',false,'Su función es indemnizatoria y está sujeta al daño y límites aplicables.'),
mc('¿Qué describe una franquicia en el supuesto usual de deducible?',['La parte del daño a cargo del asegurado según el contrato','El documento que emite el banco','La eliminación de todo riesgo'],'La franquicia deducible determina una porción a cargo del asegurado, conforme a sus condiciones.')])
];
